package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.*;
import org.springframework.security.core.Authentication;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class TaskProfessionalPackageAuthoringControllerTest {
 final ApplicationSessionIdentity identities=mock(ApplicationSessionIdentity.class);final TaskProfessionalPackageAuthoringService service=mock(TaskProfessionalPackageAuthoringService.class);final Authentication authentication=mock(Authentication.class);final ApplicationSessionIdentity.Verified subject=mock(ApplicationSessionIdentity.Verified.class);final TaskProfessionalPackageAuthoringController controller=new TaskProfessionalPackageAuthoringController(identities,service);
 MockHttpServletRequest request(){var q=new MockHttpServletRequest();q.addHeader("X-Schema-Version","1.0.0");q.addHeader("X-Context-Revision","7");q.addHeader("Idempotency-Key","original-package-key-001");q.setContent("{}".getBytes(java.nio.charset.StandardCharsets.UTF_8));return q;}
 @Test void rejectsDuplicateHeadersAndDenialBeforeBodyConsumption()throws Exception{var q=spy(request());when(identities.requireCurrent(q,authentication)).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->controller.create(q,new MockHttpServletResponse(),authentication,TaskProfessionalPackageAuthoringSchemaTest.id(3)));verify(q,never()).getInputStream();verifyNoInteractions(service);var duplicate=request();duplicate.addHeader("X-Context-Revision","8");assertThrows(SchemaRejection.class,()->controller.create(duplicate,new MockHttpServletResponse(),authentication,TaskProfessionalPackageAuthoringSchemaTest.id(3)));}
 @Test void onlyExplicitCommittedRejectionEmitsExactHeaders()throws Exception{var json=new PermissionSchema();var p=json.object().put("project_id",TaskProfessionalPackageAuthoringSchemaTest.id(3)).put("request_id",TaskProfessionalPackageAuthoringSchemaTest.id(4)).put("context_revision","7").put("key_sha256","a".repeat(64)).put("wire_sha256","b".repeat(64)).put("error_code","ACCESS_DENIED");var r=new MockHttpServletResponse();assertNull(TaskProfessionalPackageAuthoringController.respond(r,new TaskProfessionalPackageAuthoringService.Response(403,null,p)));assertEquals("REJECTED_PRE_INTENT",r.getHeader("X-Task-Package-Outcome"));assertEquals("a".repeat(64),r.getHeader("X-Task-Package-Key-Sha256"));assertEquals("b".repeat(64),r.getHeader("X-Task-Package-Wire-Sha256"));var body=new com.fasterxml.jackson.databind.ObjectMapper().readTree(r.getContentAsByteArray());assertTrue(body.required("operation_id").isNull());assertEquals(r.getHeader("X-Request-Id"),body.required("request_id").textValue());}
 @Test void ordinaryAccessErrorCannotMasqueradeAsPreIntentRejection()throws Exception{var r=new MockHttpServletResponse();controller.denied(new TenantAccessException(ErrorCode.ACCESS_DENIED),r);assertNull(r.getHeader("X-Task-Package-Outcome"));assertEquals(403,r.getStatus());}
 @Test void recoveryRejectsNewIdempotencyKeyAndReadRejectsBodies()throws Exception{var q=request();assertThrows(SchemaRejection.class,()->controller.recover(q,new MockHttpServletResponse(),authentication,TaskProfessionalPackageAuthoringSchemaTest.id(3)));assertThrows(SchemaRejection.class,()->controller.read(q,new MockHttpServletResponse(),authentication,TaskProfessionalPackageAuthoringSchemaTest.id(3),TaskProfessionalPackageAuthoringSchemaTest.id(4)));verifyNoInteractions(identities,service);}
 @Test void routeSurfaceContainsNoReleaseCredentialOrModelActions(){var routes=new TreeSet<String>();for(var method:TaskProfessionalPackageAuthoringController.class.getDeclaredMethods()){var get=method.getAnnotation(org.springframework.web.bind.annotation.GetMapping.class);var post=method.getAnnotation(org.springframework.web.bind.annotation.PostMapping.class);if(get!=null)routes.addAll(List.of(get.value()));if(post!=null)routes.addAll(List.of(post.value()));}assertEquals(Set.of("/api/projects/{projectId}/task-professional-package-preparation","/api/projects/{projectId}/task-professional-packages","/api/projects/{projectId}/task-professional-packages/{operationId}","/api/projects/{projectId}/task-professional-package-recoveries"),routes);}
}
